INSERT INTO owned_grammar_pattern_guard SELECT IF((SELECT COUNT(*) FROM grammar_point g JOIN lesson l ON l.id=g.lesson_id JOIN unit u ON u.id=l.unit_id JOIN textbook t ON t.id=u.textbook_id WHERE t.source_code=CONVERT(0x4c502d4f574e45442d5348494e4b414e5a454e2d4d41535445522d4e31 USING utf8mb4) COLLATE utf8mb4_0900_as_cs)=97,1,0);
INSERT INTO owned_grammar_pattern_guard SELECT IF((SELECT COUNT(*) FROM owned_grammar_pattern_patch p JOIN lesson l ON l.source_code=p.lesson_source_code JOIN grammar_point g ON g.lesson_id=l.id AND g.order_index=p.order_index JOIN unit u ON u.id=l.unit_id JOIN textbook t ON t.id=u.textbook_id WHERE t.source_code=CONVERT(0x4c502d4f574e45442d5348494e4b414e5a454e2d4d41535445522d4e31 USING utf8mb4) COLLATE utf8mb4_0900_as_cs AND (BINARY g.pattern=BINARY p.old_pattern OR BINARY g.pattern=BINARY p.new_pattern))=97,1,0);
INSERT INTO owned_grammar_pattern_guard SELECT IF((SELECT COUNT(DISTINCT g.id) FROM owned_grammar_pattern_patch p JOIN lesson l ON l.source_code=p.lesson_source_code JOIN grammar_point g ON g.lesson_id=l.id AND g.order_index=p.order_index JOIN unit u ON u.id=l.unit_id JOIN textbook t ON t.id=u.textbook_id WHERE t.source_code=CONVERT(0x4c502d4f574e45442d5348494e4b414e5a454e2d4d41535445522d4e31 USING utf8mb4) COLLATE utf8mb4_0900_as_cs)=97,1,0);
START TRANSACTION;
UPDATE grammar_point g JOIN lesson l ON l.id=g.lesson_id JOIN owned_grammar_pattern_patch p ON p.lesson_source_code=l.source_code AND p.order_index=g.order_index JOIN unit u ON u.id=l.unit_id JOIN textbook t ON t.id=u.textbook_id SET g.pattern=p.new_pattern WHERE t.source_code=CONVERT(0x4c502d4f574e45442d5348494e4b414e5a454e2d4d41535445522d4e31 USING utf8mb4) COLLATE utf8mb4_0900_as_cs AND BINARY g.pattern=BINARY p.old_pattern;
INSERT INTO owned_grammar_pattern_guard SELECT IF((SELECT COUNT(*) FROM owned_grammar_pattern_patch p JOIN lesson l ON l.source_code=p.lesson_source_code JOIN grammar_point g ON g.lesson_id=l.id AND g.order_index=p.order_index JOIN unit u ON u.id=l.unit_id JOIN textbook t ON t.id=u.textbook_id WHERE t.source_code=CONVERT(0x4c502d4f574e45442d5348494e4b414e5a454e2d4d41535445522d4e31 USING utf8mb4) COLLATE utf8mb4_0900_as_cs AND BINARY g.pattern=BINARY p.new_pattern)=97,1,0);
COMMIT;
